import polygons from './data/land.js';
const RAD=Math.PI/180,DEG=180/Math.PI,EARTH=6371;
export const LOCATIONS=[{name:'上海',lat:31.23,lon:121.47},{name:'东京',lat:35.67,lon:139.65},{name:'香港',lat:22.32,lon:114.17},{name:'新加坡',lat:1.35,lon:103.82},{name:'悉尼',lat:-33.87,lon:151.2},{name:'巴黎',lat:48.85,lon:2.35},{name:'伦敦',lat:51.51,lon:-.13},{name:'纽约',lat:40.71,lon:-74},{name:'旧金山',lat:37.77,lon:-122.42}];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const bounds=polygons.map(rings=>{const ring=rings[0];return{rings,minX:Math.min(...ring.map(p=>p[0])),maxX:Math.max(...ring.map(p=>p[0])),minY:Math.min(...ring.map(p=>p[1])),maxY:Math.max(...ring.map(p=>p[1]))}});
function inRing(lon,lat,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const [xi,yi]=ring[i],[xj,yj]=ring[j];if((yi>lat)!==(yj>lat)&&lon<(xj-xi)*(lat-yi)/(yj-yi)+xi)inside=!inside}return inside}
export function isLand(lat,lon){lon=((lon+180)%360+360)%360-180;for(const b of bounds){if(lon<b.minX||lon>b.maxX||lat<b.minY||lat>b.maxY)continue;if(inRing(lon,lat,b.rings[0])&&!b.rings.slice(1).some(r=>inRing(lon,lat,r)))return true}return false}
export function bearing(a,b){const p=a.lat*RAD,q=b.lat*RAD,d=(b.lon-a.lon)*RAD;return(Math.atan2(Math.sin(d)*Math.cos(q),Math.cos(p)*Math.sin(q)-Math.sin(p)*Math.cos(q)*Math.cos(d))*DEG+360)%360}
function vector(p){return[Math.cos(p.lat*RAD)*Math.cos(p.lon*RAD),Math.cos(p.lat*RAD)*Math.sin(p.lon*RAD),Math.sin(p.lat*RAD)]}
export function greatCircle(a,b,t){const u=vector(a),v=vector(b),angle=Math.acos(clamp(u.reduce((s,n,i)=>s+n*v[i],0),-1,1));if(angle<1e-7)return{...a};const k=Math.sin((1-t)*angle)/Math.sin(angle),l=Math.sin(t*angle)/Math.sin(angle),p=u.map((n,i)=>n*k+v[i]*l);return{lat:Math.atan2(p[2],Math.hypot(p[0],p[1]))*DEG,lon:Math.atan2(p[1],p[0])*DEG}}
function offset(p,heading,km){const d=km/EARTH,b=heading*RAD,lat=p.lat*RAD,lon=p.lon*RAD;const q=Math.asin(Math.sin(lat)*Math.cos(d)+Math.cos(lat)*Math.sin(d)*Math.cos(b));return{lat:q*DEG,lon:((lon+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(lat),Math.cos(d)-Math.sin(lat)*Math.sin(q)))*DEG+540)%360-180}}
export function makeRoute(origin,destination){const a=LOCATIONS[origin],b=LOCATIONS[destination],samples=[];for(let i=0;i<=160;i++){const t=i/160,p=greatCircle(a,b,t);samples.push({...p,t,land:isLand(p.lat,p.lon)})}return{origin,destination,a,b,samples,initialBearing:bearing(a,b),oceanFraction:samples.filter(p=>!p.land).length/samples.length,seed:origin*131+destination*719};}
export function routePosition(route,x,z){const t=clamp((-z-800)/11900,0,1),p=greatCircle(route.a,route.b,t),b=t<.999?bearing(p,greatCircle(route.a,route.b,Math.min(1,t+.001))):bearing(greatCircle(route.a,route.b,.999),route.b);return{...offset(p,b+90,x*.012),heading:b,progress:t};}
function hash(x,y,seed){const n=Math.sin(x*127.1+y*311.7+seed)*43758.5453;return n-Math.floor(n)}
function noise(x,y,seed){const i=Math.floor(x),j=Math.floor(y),u=x-i,v=y-j,a=u*u*(3-2*u),b=v*v*(3-2*v);return (hash(i,j,seed)*(1-a)+hash(i+1,j,seed)*a)*(1-b)+(hash(i,j+1,seed)*(1-a)+hash(i+1,j+1,seed)*a)*b}
export function elevation(route,x,z){const p=routePosition(route,x,z);let land=isLand(p.lat,p.lon);const airport=Math.min(Math.abs(z+350),Math.abs(z+13600));const urban=airport<1300&&Math.abs(x)<1100;if(urban)land=true;if(!land)return -30-12*noise(x*.001,z*.001,route.seed);if(urban)return 0;const n=noise(x*.0008,z*.0006,route.seed)*.58+noise(x*.002,z*.0017,route.seed)*.28+noise(x*.007,z*.006,route.seed)*.14;const side=clamp((Math.abs(x)-600)/2300,0,1),latitude=Math.abs(p.lat);return 8+Math.pow(n,2.1)*(100+side*(latitude>25?900:650));}
export function headingAt(route,f){return(routePosition(route,f.x,f.z).heading-f.yaw*DEG+360)%360}
